	public static void saveByteArrayToFile(byte[] pdfBytes, String directoryPath, String fileName) {
		// Verificar si la carpeta existe, si no, crearla
		File directory = new File(directoryPath);
		if (!directory.exists()) {
			directory.mkdirs();
		}

		// Ruta completa del archivo
		File file = new File(directoryPath + File.separator + fileName);

		// Escribir los bytes en el archivo
		try (FileOutputStream fos = new FileOutputStream(file)) {
			fos.write(pdfBytes);
		} catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	public static void zipFolder(String folderPath, String zipPath) throws IOException {
		File folder = new File(folderPath);
		if (!folder.exists() || !folder.isDirectory()) {
			throw new IOException("El directorio no existe: " + folderPath);
		}

		try (FileOutputStream fos = new FileOutputStream(zipPath);
			 ZipOutputStream zos = new ZipOutputStream(fos)) {

			zipFile(folder, folder.getName(), zos);
		}
	}

	private static void zipFile(File file, String baseName, ZipOutputStream zos) {
		if (file.isDirectory()) {
			for (File childFile : Objects.requireNonNull(file.listFiles())) {
				zipFile(childFile, baseName + "/" + childFile.getName(), zos);
			}
		}
	}

	private static Date extractDateToString(String fileName) {
		try {
			Path path = Paths.get(Date.class.getClassLoader().getResource(fileName).getPath());
			byte[] dateBytes = Files.readAllBytes(path);
			String date = new String(dateBytes);
			return new Date(date);
		} catch (Exception e) {
			return new Date();
		}
	}



